/* The manifest is generated by the analysis pipeline. Text is inserted with
   textContent so run metadata cannot become executable page markup. */
(() => {
  'use strict';
  const content = document.getElementById('results-content');
  const filters = document.getElementById('results-filters');
  const statusLabel = document.getElementById('study-status');
  const updatedLabel = document.getElementById('last-updated');
  let runs = [];

  function element(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = String(text);
    return node;
  }

  function titleCase(value) {
    return String(value).replaceAll('_', ' ').replace(/\b\w/g, char => char.toUpperCase());
  }

  function displayValue(value) {
    if (value === null || value === undefined) return '—';
    if (typeof value === 'number') {
      if (!Number.isFinite(value)) return '—';
      if (value !== 0 && (Math.abs(value) < 0.001 || Math.abs(value) >= 1e6)) return value.toExponential(3);
      return new Intl.NumberFormat('en-US', { maximumSignificantDigits: 7 }).format(value);
    }
    if (Array.isArray(value)) return value.map(displayValue).join(', ');
    return typeof value === 'object' ? JSON.stringify(value) : String(value);
  }

  function safeUrl(value) {
    if (typeof value !== 'string' || !value.trim()) return null;
    try {
      const parsed = new URL(value, document.baseURI);
      return ['http:', 'https:'].includes(parsed.protocol) ? parsed.href : null;
    } catch (_) { return null; }
  }

  function renderFigure(figure) {
    const url = safeUrl(figure.src);
    if (!url) return null;
    const container = element('figure', 'result-figure');
    const link = element('a');
    link.href = url;
    link.setAttribute('aria-label', `Open full-size figure: ${figure.alt || figure.caption || 'simulation result'}`);
    const img = element('img');
    img.src = url;
    img.alt = figure.alt || figure.caption || 'Simulation result; see the run description for context.';
    img.loading = 'lazy';
    img.decoding = 'async';
    img.addEventListener('error', () => {
      link.replaceWith(element('div', 'figure-unavailable', 'Figure file unavailable. Check the run artifact.'));
    }, { once: true });
    link.append(img);
    container.append(link);
    if (figure.caption) container.append(element('figcaption', '', figure.caption));
    return container;
  }

  function renderRun(run) {
    const card = element('article', 'run-card');
    const heading = element('div', 'run-heading');
    const titles = element('div');
    titles.append(element('p', 'run-id', run.id || run.case || 'Simulation run'));
    titles.append(element('h3', '', run.label || run.id || 'Simulation run'));
    const status = String(run.status || 'unreported').toLowerCase();
    const statusTag = element('span', 'run-status', titleCase(status));
    if (/^[a-z-]+$/.test(status)) statusTag.classList.add(status);
    heading.append(titles, statusTag);
    card.append(heading);
    if (run.summary) card.append(element('p', 'run-summary', run.summary));
    const details = element('div', 'run-details');
    for (const [key, label] of [['case', 'Case'], ['ng', 'Grid NG'], ['t_final', 'Final time'], ['t_target', 'Target time'], ['seed', 'Seed'], ['cfl', 'Time-step factor']]) {
      if (run[key] !== undefined && run[key] !== null) {
        const item = element('span', '', label);
        item.append(element('strong', '', displayValue(run[key])));
        details.append(item);
      }
    }
    if (details.childElementCount) card.append(details);
    if (run.metrics && typeof run.metrics === 'object') {
      const metrics = element('dl', 'metric-grid');
      for (const [key, datum] of Object.entries(run.metrics)) {
        const structured = datum && typeof datum === 'object' && !Array.isArray(datum);
        const metric = element('div', 'metric');
        metric.append(element('dt', '', structured ? datum.label || titleCase(key) : titleCase(key)));
        const value = element('dd', '', displayValue(structured ? datum.value : datum));
        if (structured && datum.unit) value.append(element('small', '', datum.unit));
        metric.append(value);
        metrics.append(metric);
      }
      if (metrics.childElementCount) card.append(metrics);
    }
    if (Array.isArray(run.figures) && run.figures.length) {
      const grid = element('div', `figure-grid${run.figures.length === 1 ? ' single' : ''}`);
      run.figures.forEach(figure => {
        if (figure && typeof figure === 'object') {
          const rendered = renderFigure(figure);
          if (rendered) grid.append(rendered);
        }
      });
      if (grid.childElementCount) card.append(grid);
    }
    if (Array.isArray(run.links)) {
      const links = element('div', 'run-links');
      run.links.forEach(item => {
        const url = safeUrl(item.href || item.url);
        if (url) { const link = element('a', '', item.label || 'Run artifact'); link.href = url; links.append(link); }
      });
      if (links.childElementCount) card.append(links);
    }
    return card;
  }

  function renderRuns(selectedCase = 'all') {
    content.replaceChildren();
    const selected = selectedCase === 'all' ? runs : runs.filter(run => String(run.case || 'Other') === selectedCase);
    selected.forEach(run => content.append(renderRun(run)));
    for (const button of filters.querySelectorAll('button')) button.setAttribute('aria-pressed', String(button.dataset.case === selectedCase));
  }

  function renderFilters() {
    const cases = [...new Set(runs.map(run => String(run.case || 'Other')))];
    if (cases.length < 2) return;
    filters.hidden = false;
    for (const value of ['all', ...cases]) {
      const button = element('button', 'filter-button', value === 'all' ? `All runs (${runs.length})` : titleCase(value));
      button.type = 'button';
      button.dataset.case = value;
      button.setAttribute('aria-pressed', String(value === 'all'));
      button.addEventListener('click', () => renderRuns(value));
      filters.append(button);
    }
  }

  async function loadResults() {
    try {
      const response = await fetch('results.json', { cache: 'no-cache' });
      if (!response.ok) throw new Error(`Manifest returned HTTP ${response.status}`);
      const manifest = await response.json();
      if (!manifest || typeof manifest !== 'object' || !Array.isArray(manifest.runs)) throw new Error('Invalid run manifest');
      runs = manifest.runs.filter(run => run && typeof run === 'object');
      if (typeof manifest.status === 'string') statusLabel.textContent = manifest.status;
      if (manifest.updated_at) {
        const date = new Date(manifest.updated_at);
        if (!Number.isNaN(date.getTime())) updatedLabel.textContent = `Updated ${new Intl.DateTimeFormat('en-US', { dateStyle: 'medium', timeZone: 'UTC' }).format(date)}`;
      }
      if (runs.some(run => ['completed', 'tested', 'validated'].includes(String(run.status).toLowerCase()))) document.getElementById('study-dot').classList.add('ready');
      if (runs.length) { renderFilters(); renderRuns(); }
    } catch (error) {
      statusLabel.textContent = 'Results manifest unavailable';
      const note = content.querySelector('.empty-state p');
      if (note) note.textContent = 'The run manifest could not be loaded. Open this page through a web server, or inspect results.json directly.';
      const heading = content.querySelector('.empty-state h3');
      if (heading) heading.textContent = 'Unable to load results';
      console.warn('Results catalog:', error.message);
    }
  }
  loadResults();
})();
